CREATE OR REPLACE PROCEDURE sp(para_Budgeted integer, para_total_budget_percent_invested real, para_Budget_invested_percent text, para_total_budget_percent_budgeted real)
LANGUAGE plpgsql AS $$
DECLARE total_sum NUMERIC;
BEGIN
    SELECT SUM("Budgeted") INTO total_sum FROM "budget";
    IF total_sum > para_Budgeted THEN
        UPDATE "budget" SET "total_budget_percent_invested" = para_total_budget_percent_invested WHERE "Budget_invested_percent" = para_Budget_invested_percent;
        UPDATE "budget" SET "Invested" = CAST(ROUND("Budgeted" * (para_total_budget_percent_invested::numeric / 100.0)) AS integer) WHERE "Budget_invested_percent" = para_Budget_invested_percent;
        UPDATE "budget" SET "Budgeted" = "Invested" WHERE "Budget_invested_percent" = para_Budget_invested_percent AND "Invested" > "Budgeted";
        UPDATE "budget" SET "Budget_invested_percent" = CASE WHEN "Budgeted" = 0 THEN '0.0' ELSE CAST(ROUND(("Invested"::numeric / "Budgeted") * 100.0, 1) AS text) END WHERE "Budget_invested_percent" = para_Budget_invested_percent;
    ELSE
        DELETE FROM "budget" WHERE "total_budget_percent_budgeted" < para_total_budget_percent_budgeted;
        SELECT SUM("Budgeted") INTO total_sum FROM "budget";
        UPDATE "budget" SET "total_budget_percent_budgeted" = CASE WHEN total_sum IS NULL OR total_sum = 0 THEN 0.0 ELSE CAST(ROUND(("Budgeted"::numeric / total_sum) * 100.0, 1) AS real) END;
        UPDATE "budget" SET "Budget_invested_percent" = CASE WHEN "Budgeted" = 0 THEN '0.0' ELSE CAST(ROUND(("Invested"::numeric / "Budgeted") * 100.0, 1) AS text) END;
    END IF;
    UPDATE "budget" SET "total_budget_percent_invested" = 0.0 WHERE "Invested" = 0;
END;
$$;
